-- Audit IDs are generated by PostgreSQL so a runtime-controlled value cannot
-- reserve an identifier needed by an authorization transition.
ALTER TABLE omnis.authorization_audit
  ALTER COLUMN id SET DEFAULT gen_random_uuid()::text;

-- Expiry is observed on reads and may be recorded concurrently by multiple
-- authorizer requests. This index makes that one lifecycle event idempotent.
CREATE UNIQUE INDEX authorization_audit_expiry_once_idx
  ON omnis.authorization_audit (authorization_id)
  WHERE event_type = 'authorization.expired';

-- Replace the original consumption routine so its required audit record uses
-- the database-generated ID and remains in the admission transaction.
CREATE OR REPLACE FUNCTION omnis.consume_run_authorization(
  p_authorization_id text,
  p_task_id text,
  p_actor_id text,
  p_run_id text,
  p_correlation_id text
) RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, omnis
AS $function$
DECLARE
  updated_id text;
BEGIN
  -- Enforce the same ordering even for callers that invoke this routine
  -- directly instead of entering through PostgresRunStore.admitRun.
  PERFORM pg_catalog.pg_advisory_xact_lock(70463909136524);

  UPDATE omnis.runtime_authorizations
     SET consumed_at = now(), consumed_run_id = p_run_id
   WHERE id = p_authorization_id
     AND requesting_actor = p_actor_id
     AND task_id = p_task_id
     AND runtime_id = 'mock'
     AND operation = 'execute_task'
     AND capabilities = '["mock.execute"]'::jsonb
     AND scope = jsonb_build_object('kind', 'task', 'taskId', p_task_id)
     AND status = 'authorized'
     AND expires_at > now()
     AND revoked_at IS NULL
     AND consumed_at IS NULL
     AND EXISTS (
       SELECT 1 FROM omnis.runs r
        WHERE r.id = p_run_id AND r.task_id = p_task_id AND r.status = 'queued'
     )
  RETURNING id INTO updated_id;

  IF updated_id IS NULL THEN
    RETURN false;
  END IF;

  INSERT INTO omnis.authorization_audit (
    authorization_id, task_id, run_id, event_type, actor_id,
    effective_identity, capability, correlation_id, outcome
  ) VALUES (
    p_authorization_id, p_task_id, p_run_id, 'authorization.consumed', p_actor_id,
    'service:omnis-worker', 'mock.execute', p_correlation_id, 'allowed'
  );
  RETURN true;
END
$function$;

-- Runtime execution may append only its own allowlisted operation events. The
-- routine derives the actor, task, authorization, correlation and outcome from
-- durable rows; no caller-supplied JSON or actor identity is trusted.
CREATE FUNCTION omnis.append_runtime_authorization_audit(
  p_run_id text,
  p_event_type text,
  p_reason_code text
) RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, omnis
AS $function$
DECLARE
  task_id text;
  authorization_id text;
  requesting_actor text;
  correlation_id text;
  run_status text;
  event_outcome text;
BEGIN
  IF session_user <> 'omnis_runtime' THEN
    RAISE EXCEPTION 'runtime audit append requires the runtime database identity'
      USING ERRCODE = '42501';
  END IF;

  IF p_event_type NOT IN (
    'authorization.enforcement_denied',
    'operation.started', 'operation.completed', 'operation.failed',
    'operation.cancelled', 'operation.interrupted'
  ) THEN
    RAISE EXCEPTION 'runtime audit event type is not permitted'
      USING ERRCODE = '42501';
  END IF;

  IF p_reason_code IS NOT NULL AND p_reason_code NOT IN (
    'missing_expired_or_revoked', 'revoked_before_completion', 'runtime_failed'
  ) THEN
    RAISE EXCEPTION 'runtime audit reason code is not permitted'
      USING ERRCODE = '22023';
  END IF;

  SELECT r.task_id, r.status, a.id, a.requesting_actor, a.correlation_id
    INTO task_id, run_status, authorization_id, requesting_actor, correlation_id
    FROM omnis.runs AS r
    JOIN omnis.runtime_authorizations AS a
      ON a.consumed_run_id = r.id AND a.task_id = r.task_id
   WHERE r.id = p_run_id;

  IF authorization_id IS NULL THEN
    RETURN false;
  END IF;

  IF (p_event_type = 'operation.started' AND run_status <> 'running') OR
     (p_event_type = 'operation.completed' AND run_status <> 'completed') OR
     (p_event_type = 'operation.failed' AND run_status <> 'failed') OR
     (p_event_type = 'operation.cancelled' AND run_status <> 'cancelled') OR
     (p_event_type IN ('operation.interrupted', 'authorization.enforcement_denied')
       AND run_status <> 'interrupted') THEN
    RAISE EXCEPTION 'runtime audit event does not match the persisted run state'
      USING ERRCODE = '23514';
  END IF;

  event_outcome := CASE
    WHEN p_event_type = 'authorization.enforcement_denied' THEN 'denied'
    WHEN p_event_type IN ('operation.started', 'operation.completed') THEN 'allowed'
    ELSE 'recorded'
  END;

  INSERT INTO omnis.authorization_audit (
    authorization_id, task_id, run_id, event_type, actor_id,
    effective_identity, capability, correlation_id, outcome, reason_code
  ) VALUES (
    authorization_id, task_id, p_run_id, p_event_type, requesting_actor,
    'service:omnis-runtime', 'mock.execute', correlation_id, event_outcome, p_reason_code
  );
  RETURN true;
END
$function$;

REVOKE ALL ON FUNCTION omnis.append_runtime_authorization_audit(text, text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION omnis.append_runtime_authorization_audit(text, text, text) FROM omnis_authorizer;
GRANT EXECUTE ON FUNCTION omnis.append_runtime_authorization_audit(text, text, text) TO omnis_runtime;

-- Remove both relation-wide and the older per-column INSERT grants.
REVOKE ALL PRIVILEGES ON TABLE omnis.authorization_audit FROM omnis_runtime;
REVOKE INSERT (
  id, authorization_id, task_id, run_id, event_type, actor_id,
  effective_identity, capability, correlation_id, outcome, reason_code, occurred_at
) ON omnis.authorization_audit FROM omnis_runtime;

-- Admission and grant consumption both take the same transaction-level
-- advisory lock before locking the authorization. Revocation takes it before
-- reading consumed_run_id. For an unconsumed grant, lock the authorization and
-- re-read consumption without an explicit task FOR UPDATE: its audit FK takes
-- only KEY SHARE, which is compatible with a caller's candidate-run FK lock.
-- If the value changed, return a retry outcome so the caller starts a fresh
-- transaction and uses the consumed run-then-authorization order.
DROP FUNCTION omnis.revoke_run_authorization(text, text);
CREATE FUNCTION omnis.revoke_run_authorization(
  p_authorization_id text,
  p_actor_id text
) RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, omnis
AS $function$
DECLARE
  target_run_id text;
  current_run_id text;
  target_task_id text;
  target_correlation_id text;
  current_status text;
  current_revoked_at timestamptz;
BEGIN
  IF p_actor_id <> 'owner' THEN
    RETURN 'inactive';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(70463909136524);

  SELECT task_id, consumed_run_id
    INTO target_task_id, target_run_id
    FROM omnis.runtime_authorizations
   WHERE id = p_authorization_id;
  IF NOT FOUND THEN
    RETURN 'inactive';
  END IF;

  IF target_run_id IS NULL THEN
    SELECT status, revoked_at, consumed_run_id, task_id, correlation_id
      INTO current_status, current_revoked_at, current_run_id,
           target_task_id, target_correlation_id
      FROM omnis.runtime_authorizations
     WHERE id = p_authorization_id
     FOR UPDATE;
    IF current_run_id IS NOT NULL THEN
      RETURN 'retry_consumed';
    END IF;
  ELSE
    PERFORM 1 FROM omnis.runs WHERE id = target_run_id FOR UPDATE;

    SELECT status, revoked_at, consumed_run_id, task_id, correlation_id
      INTO current_status, current_revoked_at, current_run_id,
           target_task_id, target_correlation_id
      FROM omnis.runtime_authorizations
     WHERE id = p_authorization_id
     FOR UPDATE;
    IF current_run_id IS DISTINCT FROM target_run_id THEN
      RETURN CASE WHEN current_run_id IS NULL THEN 'retry_unconsumed' ELSE 'retry_consumed' END;
    END IF;
  END IF;

  IF current_status IS DISTINCT FROM 'authorized' OR current_revoked_at IS NOT NULL THEN
    RETURN 'inactive';
  END IF;

  UPDATE omnis.runtime_authorizations
     SET status = 'revoked', revoked_at = now(), revoked_by = p_actor_id
   WHERE id = p_authorization_id;

  INSERT INTO omnis.authorization_audit (
    authorization_id, task_id, run_id, event_type, actor_id,
    effective_identity, capability, correlation_id, outcome
  ) VALUES (
    p_authorization_id, target_task_id, current_run_id, 'authorization.revoked',
    p_actor_id, 'human:owner', 'mock.execute', target_correlation_id, 'recorded'
  );

  RETURN 'revoked';
END
$function$;

REVOKE ALL ON FUNCTION omnis.revoke_run_authorization(text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION omnis.revoke_run_authorization(text, text) FROM omnis_runtime;
GRANT EXECUTE ON FUNCTION omnis.revoke_run_authorization(text, text) TO omnis_authorizer;
